      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

export class UriError extends Error {}

function checkPct(str, name) {
  if (str !== undefined && /%(?![0-9A-Fa-f]{2})/.test(str)) {
    throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
}

function checkAll(r) {
  checkPct(r.path, 'path')
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    checkPct(a.userinfo, 'userinfo')
    checkPct(a.host, 'host')
  }
  checkPct(r.query, 'query')
  checkPct(r.fragment, 'fragment')
}

const pct = (s) =>
  s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const up = h.toUpperCase()
    const ch = String.fromCharCode(parseInt(up, 16))
    return /^[A-Za-z0-9\-._~]$/.test(ch) ? ch : '%' + up
  })

export function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.authority !== undefined) s += '//' + r.authority
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
}

export function normalizeParsed(r) {
  checkAll(r)
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let authority
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    let port = a.port
    if (port === '' || (scheme !== undefined && port === DEFAULT_PORTS[scheme] && Object.hasOwn(DEFAULT_PORTS, scheme))) port = undefined
    authority = (a.userinfo !== undefined ? pct(a.userinfo) + '@' : '') + lower(pct(a.host)) + (port !== undefined ? ':' + port : '')
  }
  let path = removeDots(pct(r.path))
  if (authority !== undefined && path === '') path = '/'
  return serialize({
    scheme,
    authority,
    path,
    query: r.query === undefined ? undefined : pct(r.query),
    fragment: r.fragment === undefined ? undefined : pct(r.fragment),
  })
}

export function normalize(s) {
  return normalizeParsed(parse(s))
}

export function resolve(baseStr, refStr) {
  const base = parse(baseStr)
  const ref = parse(refStr)
  if (base.scheme === undefined) throw new UriError('the base has no scheme')
  let t
  if (ref.scheme !== undefined) {
    t = { ...ref, path: removeDots(ref.path) }
  } else if (ref.authority !== undefined) {
    t = { scheme: base.scheme, authority: ref.authority, path: removeDots(ref.path), query: ref.query, fragment: ref.fragment }
  } else if (ref.path === '') {
    t = { scheme: base.scheme, authority: base.authority, path: base.path, query: ref.query !== undefined ? ref.query : base.query, fragment: ref.fragment }
  } else {
    let path = ref.path
    if (!path.startsWith('/')) {
      if (base.authority !== undefined && base.path === '') path = '/' + path
      else {
        const i = base.path.lastIndexOf('/')
        path = i >= 0 ? base.path.slice(0, i + 1) + path : path
      }
    }
    t = { scheme: base.scheme, authority: base.authority, path: removeDots(path), query: ref.query, fragment: ref.fragment }
  }
  return normalizeParsed(t)
}
